LANGS = ['pt', 'fr', 'es', 'de', 'it']
FILES = [('en-us', 'English'), ('pt', 'Português'), ('fr', 'Français'), ('es', 'Español'), ('de', 'Deutsch'), ('it', 'Italiano')]

def tsv():
    out = []
    keys = set()
    for r in ROWS:
        assert len(r) == 6, r[0]
        assert r[0] not in keys, 'duplicate key: ' + r[0]
        keys.add(r[0])
        for c in r:
            assert '\t' not in c and '\n' not in c, c
        out.append('\t'.join(r))
    return '\n'.join(out)

def lng_file(col, ver):
    code, name = FILES[col]
    out = ['; ClevoTune language file - edit the text after the first "=" on each line.',
           '; The text before "=" is the original English text and must not be changed.',
           '; Missing or empty lines fall back to the built-in text. Lines starting with ; are comments.',
           '[info]', 'name=' + name, 'code=' + code, 'base=en', 'version=' + ver, '', '[strings]']
    for r in ROWS:
        out.append(r[0] + '=' + r[col])
    return '\r\n'.join(out) + '\r\n'
